using System.Globalization;
using System.Text.Json;
using Microsoft.Data.Sqlite;
using WAID.Application.Services;

namespace WAID.Infrastructure.Persistence;

public sealed class SqliteRepairOutcomeRepository(WaidDatabase database):IRepairOutcomeRepository
{
 public async Task AppendAsync(RepairAuditEntry entry,CancellationToken token){await using var c=database.OpenConnection();await using var q=c.CreateCommand();q.CommandText="INSERT OR IGNORE INTO repair_audit_chain(id,orchestration_id,transaction_id,repair_id,kind,occurred_utc,outcome,entry_json)VALUES($id,$orchestration,$transaction,$repair,$kind,$time,$outcome,$json)";q.Parameters.AddWithValue("$id",entry.Id.ToString());q.Parameters.AddWithValue("$orchestration",entry.OrchestrationId.ToString());q.Parameters.AddWithValue("$transaction",(object?)entry.TransactionId?.ToString()??DBNull.Value);q.Parameters.AddWithValue("$repair",entry.RepairId);q.Parameters.AddWithValue("$kind",(int)entry.Kind);q.Parameters.AddWithValue("$time",entry.OccurredAtUtc.ToString("O"));q.Parameters.AddWithValue("$outcome",(int)entry.Outcome);q.Parameters.AddWithValue("$json",JsonSerializer.Serialize(entry));await q.ExecuteNonQueryAsync(token).ConfigureAwait(false);}
 public async Task<IReadOnlyList<RepairAuditEntry>> QueryAsync(RepairAuditQuery query,CancellationToken token){if(query.Limit is<1 or>10000)throw new ArgumentOutOfRangeException(nameof(query));var result=new List<RepairAuditEntry>();await using var c=database.OpenConnection();await using var q=c.CreateCommand();var where=new List<string>();if(!string.IsNullOrWhiteSpace(query.RepairId)){where.Add("repair_id=$repair");q.Parameters.AddWithValue("$repair",query.RepairId);}if(query.Kind is{}kind){where.Add("kind=$kind");q.Parameters.AddWithValue("$kind",(int)kind);}if(query.Outcome is{}outcome){where.Add("outcome=$outcome");q.Parameters.AddWithValue("$outcome",(int)outcome);}if(query.FromUtc is{}from){where.Add("occurred_utc>=$from");q.Parameters.AddWithValue("$from",from.ToString("O"));}if(query.ToUtc is{}to){where.Add("occurred_utc<=$to");q.Parameters.AddWithValue("$to",to.ToString("O"));}q.CommandText=$"SELECT entry_json FROM repair_audit_chain {(where.Count==0?"":"WHERE "+string.Join(" AND ",where))} ORDER BY occurred_utc DESC,id DESC LIMIT $limit";q.Parameters.AddWithValue("$limit",query.Limit);await using var reader=await q.ExecuteReaderAsync(token).ConfigureAwait(false);while(await reader.ReadAsync(token).ConfigureAwait(false)){var entry=JsonSerializer.Deserialize<RepairAuditEntry>(reader.GetString(0));if(entry is not null)result.Add(entry);}return result;}
 public async Task ReplaceAggregatesAsync(IReadOnlyList<RepairOutcomeAggregate> aggregates,CancellationToken token){await using var c=database.OpenConnection();await using var transaction=await c.BeginTransactionAsync(token).ConfigureAwait(false);await using(var delete=c.CreateCommand()){delete.Transaction=(SqliteTransaction)transaction;delete.CommandText="DELETE FROM repair_outcome_aggregates";await delete.ExecuteNonQueryAsync(token).ConfigureAwait(false);}foreach(var item in aggregates){await using var q=c.CreateCommand();q.Transaction=(SqliteTransaction)transaction;q.CommandText="INSERT INTO repair_outcome_aggregates(repair_id,rebuilt_utc,aggregate_version,aggregate_json)VALUES($repair,$time,$version,$json)";q.Parameters.AddWithValue("$repair",item.RepairId);q.Parameters.AddWithValue("$time",item.RebuiltAtUtc.ToString("O"));q.Parameters.AddWithValue("$version",item.AggregateVersion);q.Parameters.AddWithValue("$json",JsonSerializer.Serialize(item));await q.ExecuteNonQueryAsync(token).ConfigureAwait(false);}await transaction.CommitAsync(token).ConfigureAwait(false);}
 public async Task<IReadOnlyList<RepairOutcomeAggregate>> GetAggregatesAsync(CancellationToken token){var result=new List<RepairOutcomeAggregate>();await using var c=database.OpenConnection();await using var q=c.CreateCommand();q.CommandText="SELECT aggregate_json FROM repair_outcome_aggregates ORDER BY repair_id";await using var reader=await q.ExecuteReaderAsync(token).ConfigureAwait(false);while(await reader.ReadAsync(token).ConfigureAwait(false)){var item=JsonSerializer.Deserialize<RepairOutcomeAggregate>(reader.GetString(0));if(item is not null)result.Add(item);}return result;}
}

public sealed class RepairOutcomeExportService(IRepairOutcomeRepository repository,string reportDirectory,TimeProvider time):IRepairOutcomeExportService
{
 public async Task<string> ExportAsync(RepairAuditQuery query,CancellationToken token){Directory.CreateDirectory(reportDirectory);var entries=await repository.QueryAsync(query,token).ConfigureAwait(false);var document=new{SchemaVersion="repair-audit-export-1.0",ExportedAtUtc=time.GetUtcNow(),RedactionNotice="Secrets, product keys, profile paths, and sensitive values are excluded.",Interpretation="Outcome statistics are descriptive and never authorize or generate repairs.",Entries=entries};var path=Path.Combine(reportDirectory,$"repair-audit-{time.GetUtcNow():yyyyMMdd-HHmmss}.json");await File.WriteAllTextAsync(path,JsonSerializer.Serialize(document,new JsonSerializerOptions{WriteIndented=true}),token).ConfigureAwait(false);return path;}
}